203172,49264467,27373847,34431201,44983991,36726278,50354614,27669673,37856846,51800808,18175362,51770639,21439695,29484272,49038513,51798553,50699603,37437584,52287050,44487743,47457029,52971819,41806841,22878877,11638538,49280744,45556783,36748552,31920237,38756670,51796391,50299756,31352122,40683539,19719350,49280557,45806638,34146141,38755817,15979907,47566361,26407365,19222954,33147301,46570620,52414735,29954670,43792637,20204985,52368026,54143895,48702199,51788050,29639777,41115134,50110767,29724769,33225307,20582588,42395094,10694930,46347072,50286389,43699213,26420425,19157849,52971599,40504515,41858417,32416075,52991689,38011838,41891398,52183608,17380976,48334404,48838439,31470587,41115110,29646253,50354584,34950709,30986719,46785943,27907354,51203271,35531821,51809967,53939471,35956914,29954696,34950498,40331016,53687703,51807278,34952909,37696868,46792429,28582202,46786284,52714164,42523068,29604180,45072869,20411169,38536870,51801066,44801314,24126334,17552447,21141369,50247845,19767923,48759937,53686226,32416099,44801935,53693593,26985882,38539372,51642760,42818314,50847374,49038487,27681342,43409569,54143917,23381491,14907371,42548247,47586466,45186227,26086721,35045768,21689107,49711398,48334365,35507302,41842383,51793467,20549042,25904611,42041583,33066784,25254989,32370837,38011842,27609657,42829567,16109519,27006470,49264605,47567223]) AS t(route_id)
),
sl AS (
  SELECT
    sl.session_id,
    MAX(sl.doj) AS doj,
    MAX(sl.src_id) AS src_id,
    MAX(sl.dst_id) AS dst_id
  FROM seat_layout_details sl
  INNER JOIN search_route_details route
    ON sl.session_id = route.session_id
    AND sl.uuid = route.uuid
  INNER JOIN target_routes tr
    ON route.route_id = tr.route_id
  WHERE sl.__time >= TIMESTAMP '2026-07-24 18:30:00'
    AND sl.__time < TIMESTAMP '2026-07-27 18:30:00'
    AND sl.channel = 'MOBILE_APP'
    AND sl.os = 'Android'
    AND sl.country = 'IND'
  GROUP BY 1
),
pax AS (
  SELECT
    pax.session_id
  FROM cust_info_details pax
  INNER JOIN sl
    ON pax.session_id = sl.session_id
    AND pax.doj = sl.doj
    AND pax.src_id = sl.src_id
    AND pax.dst_id = sl.dst_id
  WHERE pax.__time >= TIMESTAMP '2026-07-24 18:30:00'
    AND pax.__time < TIMESTAMP '2026-07-27 18:30:00'
    AND pax.channel = 'MOBILE_APP'
    AND pax.os = 'Android'
    AND pax.country = 'IND'
  GROUP BY 1
),
tco AS (
  SELECT
    tco.session_id
  FROM create_order_details tco
  INNER JOIN sl
    ON tco.session_id = sl.session_id
    AND tco.doj = sl.doj
    AND tco.src_id = sl.src_id
    AND tco.dst_id = sl.dst_id
  WHERE tco.__time >= TIMESTAMP '2026-07-24 18:30:00'
    AND tco.__time < TIMESTAMP '2026-07-27 18:30:00'
    AND tco.channel = 'MOBILE_APP'
    AND tco.os = 'Android'
    AND tco.country = 'IND'
  GROUP BY 1
),
ord AS (
  SELECT
    o.session_id
  FROM order_info_details o
  INNER JOIN sl
    ON o.session_id = sl.session_id
    AND o.doj = sl.doj
    AND o.src_id = sl.src_id
    AND o.dst_id = sl.dst_id
  WHERE o.__time >= TIMESTAMP '2026-07-24 18:30:00'
    AND o.__time < TIMESTAMP '2026-07-27 18:30:00'
    AND o.channel = 'MOBILE_APP'
    AND o.os = 'Android'
    AND o.country = 'IND'
  GROUP BY 1
),
pay AS (
  SELECT
    pay.session_id
  FROM make_payment_details pay
  INNER JOIN sl
    ON pay.session_id = sl.session_id
    AND pay.doj = sl.doj
    AND pay.src_id = sl.src_id
    AND pay.dst_id = sl.dst_id
  WHERE pay.__time >= TIMESTAMP '2026-07-24 18:30:00'
    AND pay.__time < TIMESTAMP '2026-07-27 18:30:00'
    AND pay.channel = 'MOBILE_APP'
    AND pay.os = 'Android'
    AND pay.country = 'IND'
  GROUP BY 1
),
confirm AS (
  SELECT
    c.session_id,
    c.tin
  FROM confirm_order_details c
  INNER JOIN sl
    ON c.session_id = sl.session_id
    AND c.doj = sl.doj
    AND c.src_id = sl.src_id
    AND c.dst_id = sl.dst_id
  WHERE c.__time >= TIMESTAMP '2026-07-24 18:30:00'
    AND c.__time < TIMESTAMP '2026-07-27 18:30:00'
    AND c.channel = 'MOBILE_APP'
    AND c.os = 'Android'
    AND c.country = 'IND'
    AND c.error_code = 'CONFIRMED'
    AND c.status_str = 'SUCCESS'
    AND c.tin IS NOT NULL
    AND TRIM(c.tin) <> ''
  GROUP BY 1, 2
)
SELECT
  COUNT(DISTINCT sl.session_id) AS sl_sessions,
  COUNT(DISTINCT pax.session_id) AS pax_sessions,
  COUNT(DISTINCT tco.session_id) AS tco_sessions,
  COUNT(DISTINCT ord.session_id) AS order_sessions,
  COUNT(DISTINCT pay.session_id) AS pay_sessions,
  COUNT(DISTINCT confirm.session_id) AS confirm_sessions,
  COUNT(DISTINCT confirm.tin) AS confirmed_bookings
FROM sl
LEFT JOIN pax ON sl.session_id = pax.session_id
LEFT JOIN tco ON sl.session_id = tco.session_id
LEFT JOIN ord ON sl.session_id = ord.session_id
LEFT JOIN pay ON sl.session_id = pay.session_id
LEFT JOIN confirm ON sl.session_id = confirm.session_id
